#!/bin/bash
s=$1; R=/root/bl/pf/CADETS_E3; mkdir -p $R/runs/s$s && cp $R/gt/CADETS_E3_attack_to_nids.pt $R/runs/s$s/ && chown -R 1000:1000 $R/runs/s$s
docker run --rm --name bl-pf-cadets-s$s --gpus all -m 28g --oom-score-adj 800 --shm-size 8g -v /root/ProvFusion:/pf:ro -v $R:/d -v /root/Desktop/platform/artifacts/baselines_paper/scripts:/scripts:ro baselines-pids:1 python -u /scripts/pf_train.py --rundir /d/runs/s$s -- --device 0 --dataset CADETS_E3 --data_path /d/cadets_e3_merged.pt --ground_truth_path /d/gt/CADETS_E3_gt_nids.pt --encoder gatedge --decoder gat --loss_fn sce --optimizer adam --num_layers 2 --in_drop 0.2 --attn_drop 0.1 --replace_rate 0.0 --activation prelu --linear_prob --scheduler --use_cfg --seeds $s --lr_f 0.001 --normalization_method percentile --num_hidden 64 --num_heads 2 --mask_rate 0.3 --lr 0.0015 --max_epoch 5 --max_epoch_f 50 --weight_decay 0.001 --weight_decay_f 0.0001 --alpha_l 3 --drop_edge_rate 0.0 > $R/runs/s$s/train.log 2>&1
grep -a "Final Voted (\|The adp score" $R/runs/s$s/train.log > /root/Desktop/platform/artifacts/baselines_paper/results/provfusion_CADETS_E3_s${s}_printed.txt
f=$(ls $R/runs/s$s/save_middle_results/*.pt)
docker run --rm --gpus all -v /root/ProvFusion:/pf:ro -v $R:/d:ro -v /root/Desktop/platform/artifacts/baselines_paper/scripts:/scripts:ro -v /root/Desktop/platform/artifacts/baselines_paper:/o baselines-pids:1 python -u /scripts/pf_score.py /d/runs/s$s/save_middle_results/$(basename $f) /d/cadets_e3_merged.pt /d/gt/CADETS_E3_gt_nids.pt /d/gt/CADETS_E3_attack_to_nids.pt --out /o/results/provfusion_CADETS_E3_s$s.json --label "ProvFusion CADETS_E3 seed$s published config" --scores /o/scores/provfusion_CADETS_E3_s$s.csv.gz --test_days 4 > $R/runs/s$s/score.log 2>&1
